const rule = {
  id: 'task-lifecycle',
  severity: 'blocking',
  description: 'Work on a branch must reference a GitHub issue in at least one commit message',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'every task starts from an issue; the reference is what ties the branch to it',

